import React,{useEffect,useState} from 'react';
import {Particles} from '@/registry/magicui/particles';
export default function ParticlesPlayground(){
 const [config,setConfig]=useState({quantity:180,ease:60,size:0.8,color:'#b9f9ab',vx:0,vy:0});
 useEffect(()=>{const update=e=>{if(e.data?.type==='preview:set-props')setConfig(c=>({...c,...e.data.props}));};window.addEventListener('message',update);return()=>window.removeEventListener('message',update);},[]);
 return <div className="relative flex min-h-screen w-full items-center justify-center overflow-hidden bg-background"><div className="pointer-events-none relative z-10 text-center"><p className="mb-4 text-xs tracking-[0.3em] text-muted-foreground uppercase">Movimento em cada detalhe</p><h1 className="text-6xl font-semibold tracking-tight md:text-7xl">Partículas.</h1><p className="mt-5 text-sm text-muted-foreground">Mova o cursor. O espaço acompanha você.</p></div><Particles key={JSON.stringify(config)} className="absolute inset-0 z-0" {...config}/></div>;
}

